import{_ as a,o as t,c as o,a0 as i}from"./chunks/framework.DCToIpx6.js";const u=JSON.parse('{"title":"Proposal: Detail Column Support","description":"","frontmatter":{},"headers":[],"relativePath":"changes/archive/2026-06-05-detail-column-support/proposal.md","filePath":"changes/archive/2026-06-05-detail-column-support/proposal.md"}'),l={name:"changes/archive/2026-06-05-detail-column-support/proposal.md"};function d(c,e,r,n,s,h){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="proposal-detail-column-support" tabindex="-1">Proposal: Detail Column Support <a class="header-anchor" href="#proposal-detail-column-support" aria-label="Permalink to &quot;Proposal: Detail Column Support&quot;">​</a></h1><h2 id="intent" tabindex="-1">Intent <a class="header-anchor" href="#intent" aria-label="Permalink to &quot;Intent&quot;">​</a></h2><p>Enable hidden detail fields in table rows so that clicking a clickable cell emits associated detail data to the parent. The parent then opens a ConfirmationDialog modal with that data, fetched dynamically from the backend.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><h3 id="in-scope" tabindex="-1">In Scope <a class="header-anchor" href="#in-scope" aria-label="Permalink to &quot;In Scope&quot;">​</a></h3><ul><li>Extend <code>TableColumn</code> with optional <code>detail</code>, <code>detailFrom</code> properties</li><li>When a <code>clickeable</code> cell is clicked, collect all <code>detail: true</code> fields from that row and emit them in the <code>cellClick</code> payload</li><li>Refactor <code>tabla-consulta-ordenes-subasta</code> to call API, build dynamic columns, handle cellClick, and open ConfirmationDialog</li><li>Add optional date input + search button for <code>executionTime</code> filter</li><li>Error handling via SweetAlert modal</li></ul><h3 id="out-of-scope" tabindex="-1">Out of Scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of Scope&quot;">​</a></h3><ul><li>Other tables reusing this detail pattern (deferred to consumer choice)</li><li>Keyboard navigation or focus management for the detail modal</li><li>Server-side pagination for the dynamic table</li></ul><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><h3 id="new-capabilities" tabindex="-1">New Capabilities <a class="header-anchor" href="#new-capabilities" aria-label="Permalink to &quot;New Capabilities&quot;">​</a></h3><p>None — extending existing capability only.</p><h3 id="modified-capabilities" tabindex="-1">Modified Capabilities <a class="header-anchor" href="#modified-capabilities" aria-label="Permalink to &quot;Modified Capabilities&quot;">​</a></h3><ul><li><code>dynamic-column-config</code>: add <code>detail</code> (boolean) and <code>detailFrom</code> (string) properties to column configuration. When <code>detail: true</code>, the column carries invisible data (already <code>visible: false</code>). On <code>clickeable</code> cell click, all <code>detail: true</code> fields from that row are collected and emitted as <code>detailData</code> in the <code>cellClick</code> payload.</li></ul><h2 id="approach" tabindex="-1">Approach <a class="header-anchor" href="#approach" aria-label="Permalink to &quot;Approach&quot;">​</a></h2><ol><li><strong>Interface</strong>: Add optional <code>detail?: boolean</code> and <code>detailFrom?: string</code> to <code>TableColumn</code> — backward-compatible</li><li><strong>Emission</strong>: On <code>cellClick</code>, iterate row fields, collect key-value pairs where <code>detail: true</code> on the matching column, and append <code>detailData: {label, value}[]</code> to the event payload</li><li><strong>Parent API</strong>: Call <code>getOpenOperationsCurrencyData({ executionTime, market })</code> on init, map response columns to <code>TableColumn[]</code>, render rows</li><li><strong>UI</strong>: Add optional <code>[(ngModel)]</code> date input + search button in parent template; filter by <code>executionTime</code> on search</li><li><strong>Modal</strong>: On cellClick, call <code>ConfirmationDialogService.open(&#39;title&#39;, detailData)</code> without subscribing to <code>afterClosed</code>. On API error, show SweetAlert error modal</li></ol><h2 id="affected-areas" tabindex="-1">Affected Areas <a class="header-anchor" href="#affected-areas" aria-label="Permalink to &quot;Affected Areas&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Impact</th><th>Description</th></tr></thead><tbody><tr><td><code>src/app/features/shared/generic-table/interfaces/tableColumn.interface.ts</code></td><td>Modified</td><td>Add <code>detail?</code>, <code>detailFrom?</code></td></tr><tr><td><code>src/app/features/shared/generic-table-without-actions/generic-table-without-actions.component.ts</code></td><td>Modified</td><td>Collect &amp; emit <code>detailData</code> on cellClick</td></tr><tr><td><code>src/app/features/divisas/components/subasta-divisas/tabla-consulta-ordenes-subasta/...component.ts</code></td><td>Modified</td><td>Dynamic API, cellClick handler, modal open</td></tr><tr><td><code>src/app/features/divisas/components/subasta-divisas/tabla-consulta-ordenes-subasta/...component.html</code></td><td>Modified</td><td>Date input + search button</td></tr></tbody></table><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Likelihood</th><th>Mitigation</th></tr></thead><tbody><tr><td>API shape mismatch between environments</td><td>Med</td><td>Validate response shape at call site</td></tr><tr><td>Backward compat break if parent omits detail fields</td><td>Low</td><td>Optional fields, current behavior unchanged</td></tr><tr><td>Modal opened without afterClosed leaks memory</td><td>Low</td><td>ConfirmationDialogService handles its own lifecycle</td></tr></tbody></table><h2 id="rollback-plan" tabindex="-1">Rollback Plan <a class="header-anchor" href="#rollback-plan" aria-label="Permalink to &quot;Rollback Plan&quot;">​</a></h2><p><code>git revert &lt;merge-commit&gt;</code> or restore the 4 modified files from <code>HEAD~1</code>. If deployed, revert the deployment in GitLab.</p><h2 id="dependencies" tabindex="-1">Dependencies <a class="header-anchor" href="#dependencies" aria-label="Permalink to &quot;Dependencies&quot;">​</a></h2><ul><li><code>ConfirmationDialogService</code> from <code>src/app/services/confirmation-dialog.service.ts</code></li><li><code>getOpenOperationsCurrencyData</code> endpoint returning <code>{ data: { columns, rows } }</code></li><li><code>ModalSweetAlert2Service</code> from <code>src/app/features/services/modal/modal-sweetalert2-service.service.ts</code></li></ul><h2 id="success-criteria" tabindex="-1">Success Criteria <a class="header-anchor" href="#success-criteria" aria-label="Permalink to &quot;Success Criteria&quot;">​</a></h2><ul><li>[ ] <code>TableColumn</code> interface compiles with optional <code>detail</code>, <code>detailFrom</code></li><li>[ ] Clicking a clickable cell emits <code>detailData</code> in the event payload with <code>detail: true</code> fields</li><li>[ ] Parent component renders dynamic columns from API on init</li><li>[ ] ConfirmationDialog opens on cell click with correct detail data</li><li>[ ] Date filter + search button work and re-fetch with <code>executionTime</code></li><li>[ ] API errors show SweetAlert modal</li></ul>',25)])])}const m=a(l,[["render",d]]);export{u as __pageData,m as default};
